<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>VENTUS — Stormwalker Dispatch</title>
<style>
  :root {
    --ink: #0a0f16; --glass: rgba(10, 16, 24, 0.78); --line: #2c3e50;
    --cyan: #37e0ff; --amber: #ffc861; --paper: #eef3f7; --dim: #8fa3b8;
    --green: #59d98c; --red: #ff5d5d;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: var(--ink); }
  body { font-family: "Avenir Next", "Segoe UI", Inter, system-ui, sans-serif; color: var(--paper); }
  #scene { position: fixed; inset: 0; }
  canvas.webgl { display: block; }

  /* ---------- HUD ---------- */
  #hud { position: fixed; inset: 0; pointer-events: none; display: none; }
  body.flying #hud { display: block; }
  .tape {
    position: absolute; top: 84px; width: 92px; padding: 8px 0 6px; text-align: center;
    background: var(--glass); border: 1px solid var(--line); border-radius: 10px;
  }
  #tape-l { left: 18px; } #tape-r { right: 18px; }
  .tape .lab { font-size: 10px; letter-spacing: 0.18em; color: var(--dim); }
  .tape .val { font-size: 30px; font-weight: 800; line-height: 1.05; font-variant-numeric: tabular-nums; }
  .tape .sub { font-size: 11px; color: var(--dim); font-variant-numeric: tabular-nums; }
  #hdg-wrap {
    position: absolute; top: 14px; left: 50%; transform: translateX(-50%); text-align: center;
    background: var(--glass); border: 1px solid var(--line); border-radius: 10px; padding: 5px 18px 7px;
  }
  #hdg-wrap .lab { font-size: 10px; letter-spacing: 0.18em; color: var(--dim); }
  #hdg { font-size: 24px; font-weight: 800; font-variant-numeric: tabular-nums; }
  #tgt { display: block; font-size: 12.5px; color: var(--amber); margin-top: 1px; min-height: 15px; }
  #obj {
    position: absolute; top: 84px; left: 50%; transform: translateX(-50%); width: 340px;
    background: var(--glass); border: 1px solid var(--line); border-radius: 10px; padding: 8px 12px;
  }
  #obj-title { font-size: 13.5px; font-weight: 700; letter-spacing: 0.02em; }
  #obj-sub { font-size: 12px; color: var(--dim); margin-top: 1px; min-height: 14px; }
  #obj-track { height: 5px; background: #1c2836; border-radius: 3px; margin-top: 6px; }
  #obj-bar { height: 100%; width: 0%; background: var(--cyan); border-radius: 3px; transition: width 0.2s; }
  #meters {
    position: absolute; left: 18px; bottom: 16px; width: 240px;
    background: var(--glass); border: 1px solid var(--line); border-radius: 10px; padding: 9px 12px;
  }
  .mrow { display: flex; align-items: center; gap: 8px; margin-top: 5px; font-size: 10.5px; }
  .mrow:first-child { margin-top: 0; }
  .mrow .mlab { width: 58px; letter-spacing: 0.08em; color: var(--dim); }
  .mrow .mtxt { width: 74px; text-align: right; font-variant-numeric: tabular-nums; color: var(--paper); }
  .track { flex: 1; height: 8px; background: #1c2836; border-radius: 4px; overflow: hidden; }
  .fill { height: 100%; width: 0%; background: var(--cyan); }
  #fuel-fill { background: var(--amber); } #hull-fill { background: var(--green); } #thr-fill { background: #aeb9c4; }
  #shear-txt { position: absolute; left: 18px; bottom: 138px; font-size: 15px; font-weight: 800; letter-spacing: 0.14em; }
  #warn {
    position: absolute; bottom: 150px; left: 50%; transform: translateX(-50%);
    font-size: 16px; font-weight: 800; letter-spacing: 0.1em; color: var(--red); text-align: center;
    text-shadow: 0 1px 8px #000; min-height: 20px;
