    }
    if (d < c.r * 1.5) {
      const band = Math.exp(-Math.pow((d - c.r * 0.72) / (c.r * 0.34), 2));
      s = Math.max(s, band * c.strength * (0.85 + 0.15 * Math.sin(t * 0.7 + c.x)));
