}
// Lightning activity 0..1 at a point (drives harvest + flashes).
export function chargeAt(x, z) {
  let c = 0;
  for (const cell of STORM_CELLS) {
    const d = Math.hypot(x - cell.x, z - cell.z);
    if (d < cell.r) c = Math.max(c, cell.strength * (1 - d / cell.r));
  }
  return c;
}

